# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows

def make(last, first):
    return Student("id-" + last, last, first, "A")

class SeatingTests(unittest.TestCase):
    def test_sorted_and_chunked(self):
        people = [make("Halloway", "Juno"), make("Dunmere", "Piet"), make("Aldous", "Bea")]
        self.assertEqual(
            seating_rows(people, 2),
            ["Row 1: Aldous, Bea | Dunmere, Piet", "Row 2: Halloway, Juno"]
        )

    def test_bad_seat_count(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows([make("Dunmere", "Piet")], seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
